static const UiGlyph kGlyphs[] = {
  { "A", 32, 32, kA },
  { "B", 32, 32, kB },
  { "X", 32, 32, kX },
  { "Y", 32, 32, kY },
  { "BACK", 34, 32, kBACK },
  { "START", 35, 32, kSTART },
  { "LB", 62, 26, kLB },
  { "RB", 62, 26, kRB },
  { "LT", 18, 34, kLT },
  { "RT", 18, 34, kRT },
  { "LS", 31, 32, kLS },
  { "RS", 31, 32, kRS },
  { "DPAD", 32, 32, kDPAD },
  { 0, 0, 0, 0 }
};

const UiGlyph *uiGlyph(const char *name)
{
  for (const UiGlyph *g = kGlyphs; g->name; g++)
    if (strcmp(g->name, name) == 0)
      return g;
  return 0;
}
